<?php

declare(strict_types=1);

namespace App\Tools\IcmsCalculator\Presentation\Controllers; use App\Core\Access\Services\ToolFeatureRequestAuthorizer; use App\Http\Controllers\Controller; use App\Tools\IcmsCalculator\Tool; use App\Tools\IcmsCalculator\Application\Actions\CalculateTool; use App\Tools\IcmsCalculator\Application\Actions\ShowToolPage; use App\Tools\IcmsCalculator\Application\Data\CalculationInput; use App\Tools\IcmsCalculator\Presentation\Requests\ExecuteToolRequest; use Illuminate\Contracts\View\View; use Illuminate\Http\Request; final class ToolController extends Controller { public function index(Request $request,ShowToolPage $page):View{return view('tools-calculadora-icms-proprio::index',$page->execute());} public function calculate(ExecuteToolRequest $request,CalculateTool $action,ShowToolPage $page,ToolFeatureRequestAuthorizer $features,Tool $module):View{$d=$request->validated();$features->requireIf((bool)($d['value_excludes_icms']??false),$module,'inside_calculation',$request);$r=$action->execute(new CalculationInput($d['value'],$d['rate'],$d['reduction']??'0',(bool)($d['value_excludes_icms']??false)));$request->flash();return view('tools-calculadora-icms-proprio::index',[...$page->execute(),'result'=>$r]);}}
